head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.tooltip = function(label, index) {
    return "item " + index;
};
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id) {
    //var el = WebSquare.wUnit.getDomById($p.id+id);
    scwin.fireOver(document.getElementsByClassName('w2checkbox_label ')[0]);
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 style 부분을 확인한다.
    //1. Check the style section in the Source tab.
    //Test step 2. IE 브라우저에서 name1 컬럼에 ... 부분을 마우스 오버한다.
    //2. In the IE browser, mouse over the ... column in the name1 column.
    //Verify step 2. A tooltip is created. (Previous versions did not create a tooltip when that style was applied)
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_3_tooltip').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_3_tooltip').text() == 'item 0'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
